{
 "summary": "The two targets assert Fefferman's breakdown alternatives (C) and (D) for 3D incompressible Navier–Stokes. For every ν>0 there are smooth initial data and a force, with Schwartz-type decay on ℝ³ or periodic with time decay on 𝕋³, for which no smooth global solution exists; on ℝ³ the non-existent solution must also have uniformly bounded energy. The single most important caveat: `navier_stokes_breakdown_R3` carries the hypothesis `hbase : (1 : ℕ) = 0`, which is false, so the ℝ³ theorem is vacuously true and certifies nothing about alternative (C). The periodic statement appears faithful.",
 "glossary": [
  {"decl": "divergence", "line": 81, "plain": "∇·v(x) = trace of the Fréchet derivative Dv(x); equals 0 where v is not differentiable", "standard_concept": "divergence of a vector field", "matches_standard": "yes", "note": "Junk value 0 only off differentiability points. Every use is on fields required to be C^∞, so it is harmless."},
  {"decl": "IsOnePeriodic", "line": 121, "plain": "f(x+e_i)=f(x) for all x and every coordinate i", "standard_concept": "ℤⁿ-periodicity / function on 𝕋ⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityCondition", "line": 134, "plain": "u₀ is C^∞ and divergence-free", "standard_concept": "Fefferman (2) plus smoothness", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityConditionDecay", "line": 150, "plain": "In addition, for all m and real K there is C with ‖D^m u₀(x)‖ ≤ C/(1+|x|)^K", "standard_concept": "Fefferman condition (4)", "matches_standard": "yes", "note": "The base is ≥ 1, so rpow and division have no junk issues."},
  {"decl": "InitialVelocityConditionPeriodic", "line": 164, "plain": "Smooth, divergence-free, and 1-periodic initial data", "standard_concept": "Fefferman (8)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceCondition", "line": 175, "plain": "f is C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth forcing", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionDecay", "line": 185, "plain": "Within-derivatives of f of every order m satisfy ‖D^m f(x,t)‖ ≤ C/(1+|x|+t)^K for t≥0", "standard_concept": "Fefferman condition (5)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionPeriodic", "line": 200, "plain": "f is smooth and spatially 1-periodic for t≥0, with ‖D^m f(x,t)‖ ≤ C/(1+t)^K", "standard_concept": "Fefferman (8),(9)", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothness", "line": 217, "plain": "(v,p) satisfy ∂_t v + (v·∇)v = νΔv − ∇p + f and ∇·v=0 for t≥0, v(·,0)=u₀, and v,p are C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth global solution of NS", "matches_standard": "yes", "note": "One-sided time derivative at t=0; required smoothness rules out the junk-derivative cases."},
  {"decl": "NavierStokesExistenceAndSmoothnessRn", "line": 245, "plain": "In addition, v(·,t)∈L² for each t≥0 and there is E with ∫|v(x,t)|²dx < E for all t≥0", "standard_concept": "Fefferman (6),(7)", "matches_standard": "yes", "note": "MemLp 2 makes the energy integral genuine rather than a junk 0."},
  {"decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 262, "plain": "In addition, v and p are 1-periodic in space for every t≥0", "standard_concept": "Fefferman (10),(11) plus errata (periodic pressure)", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "navier_stokes_breakdown_R3", "line": 273, "plain": "Assuming 1 = 0 in ℕ (false), for every ν>0 there exist u₀ and f satisfying the decay conditions such that no smooth bounded-energy global solution (v,p) on ℝ³ exists. Since the hypothesis is false, the statement is vacuous."},
  {"theorem": "navier_stokes_breakdown_periodic", "line": 280, "plain": "For every ν>0 there exist smooth, divergence-free, 1-periodic u₀ and a smooth, 1-periodic, time-decaying f such that no smooth global spatially periodic solution (v,p) (pressure also periodic) exists."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every ν>0 there is f∈C_c^∞(ℝ³×(0,∞)) with u₀=0 such that the smooth solution blows up in L^∞ at t=1 with bounded energy. Consequently there is no smooth global solution with uniformly bounded energy, i.e. alternative (C)."},
  {"ref": "Corollary 10.6", "plain": "For every ν>0 there is a smooth force on 𝕋³×[0,∞), compactly supported in time, with zero initial data, for which no global smooth periodic solution exists, i.e. alternative (D)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "navier_stokes_breakdown_R3", "relation": "lean_weaker", "why": "The false hypothesis 1=0 makes the Lean statement vacuous."},
  {"paper_ref": "Corollary 10.6", "lean_theorem": "navier_stokes_breakdown_periodic", "relation": "equivalent", "why": "The Lean statement matches Fefferman (D), which the corollary claims. Zero data and a compactly supported force satisfy the hypotheses."}
 ],
 "flags": [
  {"id": "F1", "category": "assumption", "severity": "high", "decl": "navier_stokes_breakdown_R3", "line": 273, "paper_ref": "Theorem 1.1", "explanation": "The hypothesis `hbase : (1 : ℕ) = 0` is false. The theorem is therefore trivially provable (e.g. `absurd hbase (by decide)`) and says nothing about alternative (C).", "polarity": "lean weaker", "probe_idea": "example (h : (1:ℕ)=0) (nu : ℝ) (hnu : nu > 0) : <goal> := absurd h (by decide) — showing the target is vacuous; then require a proof of the statement without hbase."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 269, "paper_ref": "Corollary 10.6", "explanation": "Periodic pressure is required of the hypothetical solution. Inside ¬∃ this extra requirement slightly weakens the claim. It matches the Clay errata and the paper's notion of a periodic solution.", "polarity": "lean weaker", "probe_idea": null}
 ],
 "lint_verdicts": [
  {"line": 81, "rule": "junk-deriv", "verdict": "harmless", "why": "Divergence is applied only to C^∞ fields, where fderiv is genuine."},
  {"line": 155, "rule": "junk-div", "verdict": "harmless", "why": "The denominator (1+‖x‖)^K is positive for every real K."},
  {"line": 155, "rule": "junk-deriv", "verdict": "harmless", "why": "u₀ is required C^∞, so iteratedFDeriv is genuine."},
  {"line": 191, "rule": "junk-div", "verdict": "harmless", "why": "Since t≥0, the base 1+‖x‖+t is ≥ 1 and positive."},
  {"line": 205, "rule": "junk-div", "verdict": "harmless", "why": "Since t≥0, the base 1+t is ≥ 1."},
  {"line": 224, "rule": "nat-sub", "verdict": "harmless", "why": "This is subtraction in ℝ³, not ℕ."},
  {"line": 223, "rule": "junk-deriv", "verdict": "harmless", "why": "The velocity_smooth field ensures the derivatives are genuine. Any junk only enlarges the hypothetical solution set, which is ruled out anyway."},
  {"line": 253, "rule": "junk-integral", "verdict": "harmless", "why": "The `integrable` field (MemLp 2) guarantees ‖v‖² is integrable, so the integral is the true energy."}
 ]
}
